<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'; import AdminLayout from '@/Layouts/AdminLayout.vue';
const props = defineProps({ rate: Object }); const form = useForm({ account_type: props.rate?.account_type || 'individual', name: props.rate?.name || '', amount: props.rate?.amount || '', duration_months: props.rate?.duration_months || 12, active_from: props.rate?.active_from || '', active_until: props.rate?.active_until || '' }); const submit = () => props.rate ? form.put(route('admin.rates.update', props.rate.id)) : form.post(route('admin.rates.store'));
</script>
<template><Head :title="rate ? 'Ubah Tarif' : 'Tambah Tarif'"/><AdminLayout><Link :href="route('admin.rates.index')" class="text-sm font-semibold text-aski-700">← Kembali</Link><h1 class="mt-4 text-3xl font-bold text-aski-900">{{ rate ? 'Ubah Tarif' : 'Tambah Tarif' }}</h1><form class="card mt-6 max-w-2xl p-6" @submit.prevent="submit"><div class="grid gap-5 sm:grid-cols-2"><label class="text-sm font-medium">Tipe akun<select v-model="form.account_type" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"><option value="individual">Individu</option><option value="institution">Institusi</option></select></label><label class="text-sm font-medium">Nama tarif<input v-model="form.name" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"/><span class="text-xs text-red-600">{{ form.errors.name }}</span></label><label class="text-sm font-medium">Nominal (Rp)<input v-model="form.amount" type="number" min="0" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"/><span class="text-xs text-red-600">{{ form.errors.amount }}</span></label><label class="text-sm font-medium">Durasi (bulan)<input v-model="form.duration_months" type="number" min="1" max="120" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"/><span class="text-xs text-red-600">{{ form.errors.duration_months }}</span></label><label class="text-sm font-medium">Mulai aktif<input v-model="form.active_from" type="date" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"/><span class="text-xs text-red-600">{{ form.errors.active_from }}</span></label><label class="text-sm font-medium">Berakhir aktif (opsional)<input v-model="form.active_until" type="date" class="mt-1 w-full rounded-lg border-slate-300 focus:border-aski-500 focus:ring-aski-500"/><span class="text-xs text-red-600">{{ form.errors.active_until }}</span></label></div><button class="btn-primary mt-7">Simpan Tarif</button></form></AdminLayout></template>
